#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <vector>

struct Robot {
  std::int32_t x_mm = 0;
};

class Command {
 public:
  Command() = default;
  Command(const Command&) = delete;
  Command& operator=(const Command&) = delete;
  virtual ~Command() = default;
  virtual void execute(Robot& robot) = 0;
  virtual void undo(Robot& robot) = 0;
};

class MoveBy final : public Command {
 public:
  explicit MoveBy(std::int32_t delta_mm) : delta_mm_(delta_mm) {}
  void execute(Robot& robot) override { robot.x_mm += delta_mm_; }
  void undo(Robot& robot) override { robot.x_mm -= delta_mm_; }

 private:
  std::int32_t delta_mm_;
};

int main() {
  Robot robot;
  std::vector<std::unique_ptr<Command>> history;

  auto run = [&](std::unique_ptr<Command> cmd) {
    cmd->execute(robot);
    history.push_back(std::move(cmd));
  };

  run(std::make_unique<MoveBy>(500));
  run(std::make_unique<MoveBy>(300));
  std::cout << std::format("after two moves: {} mm\n", robot.x_mm);

  history.back()->undo(robot);
  history.pop_back();
  std::cout << std::format("after undo: {} mm\n", robot.x_mm);
}

