#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

struct Robot {
  std::int32_t x_mm = 0;
  std::int32_t heading_mdeg = 0;
};

// The request as an object: a description for logging, and both directions of the change.
class Command {
 public:
  Command() = default;
  Command(const Command&) = delete;
  Command& operator=(const Command&) = delete;
  virtual ~Command() = default;
  [[nodiscard]] virtual std::string describe() const = 0;
  virtual void execute(Robot& robot) = 0;
  virtual void undo(Robot& robot) = 0;
};

class MoveBy final : public Command {
 public:
  explicit MoveBy(std::int32_t delta_mm) : delta_mm_(delta_mm) {}
  [[nodiscard]] std::string describe() const override { return std::format("move by {} mm", delta_mm_); }
  void execute(Robot& robot) override { robot.x_mm += delta_mm_; }
  void undo(Robot& robot) override { robot.x_mm -= delta_mm_; }

 private:
  std::int32_t delta_mm_;
};

class TurnBy final : public Command {
 public:
  explicit TurnBy(std::int32_t delta_mdeg) : delta_mdeg_(delta_mdeg) {}
  [[nodiscard]] std::string describe() const override { return std::format("turn by {} mdeg", delta_mdeg_); }
  void execute(Robot& robot) override { robot.heading_mdeg += delta_mdeg_; }
  void undo(Robot& robot) override { robot.heading_mdeg -= delta_mdeg_; }

 private:
  std::int32_t delta_mdeg_;
};

// Coordinates a queue of commands: logs each one before running it, and can undo the whole run.
class CommandQueue {
 public:
  void push(std::unique_ptr<Command> command) { pending_.push_back(std::move(command)); }

  void run_all(Robot& robot) {
    for (auto& command : pending_) {
      std::cout << std::format("running: {}\n", command->describe());
      command->execute(robot);
      done_.push_back(std::move(command));
    }
    pending_.clear();
  }

  void undo_all(Robot& robot) {
    while (!done_.empty()) {
      std::cout << std::format("undoing: {}\n", done_.back()->describe());
      done_.back()->undo(robot);
      done_.pop_back();
    }
  }

 private:
  std::vector<std::unique_ptr<Command>> pending_;
  std::vector<std::unique_ptr<Command>> done_;
};

int main() {
  Robot robot;
  CommandQueue queue;
  queue.push(std::make_unique<MoveBy>(500));
  queue.push(std::make_unique<TurnBy>(900));
  queue.push(std::make_unique<MoveBy>(-200));

  queue.run_all(robot);
  std::cout << std::format("after the queue: x {} mm, heading {} mdeg\n", robot.x_mm, robot.heading_mdeg);

  queue.undo_all(robot);
  std::cout << std::format("after undoing all: x {} mm, heading {} mdeg\n", robot.x_mm, robot.heading_mdeg);
}

