  void execute(Robot& robot) override { robot.heading_mdeg += delta_mdeg_; }
  void undo(Robot& robot) override { robot.heading_mdeg -= delta_mdeg_; }

 private:
  std::int32_t delta_mdeg_;
};

// A command built out of other commands: one undo step for the whole group.
class MacroCommand final : public Command {
 public:
  explicit MacroCommand(std::vector<std::unique_ptr<Command>> steps) : steps_(std::move(steps)) {}

  [[nodiscard]] std::string describe() const override { return std::format("macro of {} steps", steps_.size()); }
  void execute(Robot& robot) override {
    for (auto& step : steps_) step->execute(robot);
  }
  void undo(Robot& robot) override {
    for (auto it = steps_.rbegin(); it != steps_.rend(); ++it) (*it)->undo(robot);
  }

 private:
  std::vector<std::unique_ptr<Command>> steps_;
};

int main() {
  Robot robot;

  std::vector<std::unique_ptr<Command>> steps;
  steps.push_back(std::make_unique<MoveBy>(400));
  steps.push_back(std::make_unique<TurnBy>(900));
  steps.push_back(std::make_unique<MoveBy>(200));

  std::unique_ptr<Command> square_leg = std::make_unique<MacroCommand>(std::move(steps));
  std::cout << std::format("running: {}\n", square_leg->describe());
  square_leg->execute(robot);
  std::cout << std::format("after the macro: x {} mm, heading {} mdeg\n", robot.x_mm, robot.heading_mdeg);

  square_leg->undo(robot);
  std::cout << std::format("after one undo(): x {} mm, heading {} mdeg\n", robot.x_mm, robot.heading_mdeg);
}

#include <cstddef>
#include <format>
#include <iostream>
#include <memory>
#include <string>
#include <utility>
#include <vector>

struct Document {
  std::string text;
};

class EditCommand {
 public:
  EditCommand() = default;
  EditCommand(const EditCommand&) = delete;
  EditCommand& operator=(const EditCommand&) = delete;
  virtual ~EditCommand() = default;
  virtual void execute(Document& doc) = 0;
  virtual void undo(Document& doc) = 0;
};

class InsertCommand final : public EditCommand {
 public:
  InsertCommand(std::size_t pos, std::string text) : pos_(pos), text_(std::move(text)) {}
  void execute(Document& doc) override { doc.text.insert(pos_, text_); }
  void undo(Document& doc) override { doc.text.erase(pos_, text_.size()); }

 private:
  std::size_t pos_;
  std::string text_;
};

class DeleteCommand final : public EditCommand {
 public:
  DeleteCommand(std::size_t pos, std::size_t count) : pos_(pos), count_(count) {}
  void execute(Document& doc) override {
    removed_ = doc.text.substr(pos_, count_);
    doc.text.erase(pos_, count_);
  }
  void undo(Document& doc) override { doc.text.insert(pos_, removed_); }

 private:
  std::size_t pos_;
  std::size_t count_;
  std::string removed_;
};

class History {
 public:
  void do_command(std::unique_ptr<EditCommand> command, Document& doc) {
    command->execute(doc);
    done_.push_back(std::move(command));
    undone_.clear();  // a fresh edit invalidates whatever could have been redone
  }
  bool undo(Document& doc) {
    if (done_.empty()) return false;
    done_.back()->undo(doc);
    undone_.push_back(std::move(done_.back()));
    done_.pop_back();
    return true;
  }
  bool redo(Document& doc) {
    if (undone_.empty()) return false;
    undone_.back()->execute(doc);
    done_.push_back(std::move(undone_.back()));
    undone_.pop_back();
    return true;
  }

 private:
  std::vector<std::unique_ptr<EditCommand>> done_;
  std::vector<std::unique_ptr<EditCommand>> undone_;
};

int main() {
  Document doc;
  History history;

  history.do_command(std::make_unique<InsertCommand>(0, "Hello"), doc);
  history.do_command(std::make_unique<InsertCommand>(5, " World"), doc);
  std::cout << std::format("after two inserts: \"{}\"\n", doc.text);

  history.do_command(std::make_unique<DeleteCommand>(5, 6), doc);
  std::cout << std::format("after deleting \" World\": \"{}\"\n", doc.text);

  history.undo(doc);
  std::cout << std::format("after undoing the delete: \"{}\"\n", doc.text);

  history.undo(doc);
  std::cout << std::format("after undoing the second insert: \"{}\"\n", doc.text);

  history.redo(doc);
  std::cout << std::format("after redoing: \"{}\"\n", doc.text);

  history.do_command(std::make_unique<InsertCommand>(5, "!"), doc);
  std::cout << std::format("after a fresh edit: \"{}\"\n", doc.text);
  std::cout << std::format("redo available after a fresh edit: {}\n", history.redo(doc));
}

#include <cstdint>
#include <format>
#include <functional>
#include <iostream>

struct Robot {
  std::int32_t x_mm = 0;
  std::int32_t heading_mdeg = 0;
};

struct FunctionCommand {
  std::function<void()> execute;
  std::function<void()> undo;
};

int main() {
  Robot robot;

  // The mistake: undo was copied from a different command and never updated.
  FunctionCommand turn;
  turn.execute = [&robot] { robot.heading_mdeg += 900; };
  turn.undo = [&robot] { robot.x_mm -= 900; };  // wrong field: nothing ties this to turn.execute

  turn.execute();
  std::cout << std::format("after execute: x {} mm, heading {} mdeg\n", robot.x_mm, robot.heading_mdeg);
  turn.undo();
  std::cout << std::format("after undo:    x {} mm, heading {} mdeg\n", robot.x_mm, robot.heading_mdeg);
}

#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <vector>

struct Robot {
  std::int32_t x_mm = 0;
};

class Command {
 public:
  Command() = default;
  Command(const Command&) = delete;
  Command& operator=(const Command&) = delete;
  virtual ~Command() = default;
  virtual void execute() = 0;
  virtual void undo() = 0;
};

// Binds its receiver at construction, so execute() and undo() take no arguments.
class MoveBy final : public Command {
 public:
  MoveBy(Robot& robot, std::int32_t delta_mm) : robot_(robot), delta_mm_(delta_mm) {}
  void execute() override { robot_.x_mm += delta_mm_; }
  void undo() override { robot_.x_mm -= delta_mm_; }

 private:
  Robot& robot_;
  std::int32_t delta_mm_;
};

int main() {
  std::vector<std::unique_ptr<Command>> history;
  {
    Robot robot;
    auto move = std::make_unique<MoveBy>(robot, 500);
    move->execute();
    std::cout << std::format("moved to {} mm\n", robot.x_mm);
    history.push_back(std::move(move));
  }  // robot destroyed here; the command in history still refers to it
  history.back()->undo();  // writes through a reference to a destroyed Robot
}
